class Malware:
  """Represents a generic malware program."""

  def __init__(self, name, description, infection_rate, delay):
    self.name = name
    self.description = description
    self.infection_rate = infection_rate
    self.delay = delay

  def spread(self, target_system):
    """Simulates the malware spreading to a target system."""

    print(f"{self.name} is trying to spread to: {target_system}")

    if random.uniform(0, 1) < self.infection_rate:
      print(f"{self.name} successfully spread to {target_system}")
      target_system.infect()
    else:
      print(f"{self.name} did not infect {target_system}")

  def describe(self):
    """Returns a brief description of the malware."""

    return f"{self.name} - {self.description}"


